--
-- Name: fn_audit_row_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_audit_row_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_pk_col    text := TG_ARGV[0];
    v_record_id text;
    v_actor     text := COALESCE(NULLIF(current_setting('app.actor', true), ''), session_user || '@unknown');
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_record_id := (to_jsonb(OLD) ->> v_pk_col);
        INSERT INTO audit_log (table_name, record_id, action, changed_by, changed_at, old_value, new_value)
        VALUES (TG_TABLE_NAME, v_record_id, lower(TG_OP), v_actor, clock_timestamp(), to_jsonb(OLD), NULL);
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        v_record_id := (to_jsonb(NEW) ->> v_pk_col);
        INSERT INTO audit_log (table_name, record_id, action, changed_by, changed_at, old_value, new_value)
        VALUES (TG_TABLE_NAME, v_record_id, lower(TG_OP), v_actor, clock_timestamp(), to_jsonb(OLD), to_jsonb(NEW));
        RETURN NEW;
    ELSE
        v_record_id := (to_jsonb(NEW) ->> v_pk_col);
        INSERT INTO audit_log (table_name, record_id, action, changed_by, changed_at, old_value, new_value)
        VALUES (TG_TABLE_NAME, v_record_id, lower(TG_OP), v_actor, clock_timestamp(), NULL, to_jsonb(NEW));
        RETURN NEW;
    END IF;
END;
$$;


