--
-- Name: trg_log_asset_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_log_asset_allocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_request_id bigint;
    v_device_type_id integer;
    v_asset_spec text;
    v_requested_qty integer;
    v_request_date timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NOT EXISTS (SELECT 1 FROM asset_requests WHERE resulting_allocation_id = NEW.allocation_id) THEN
            SELECT device_type_id INTO v_device_type_id FROM assets WHERE asset_id = NEW.asset_id;
            INSERT INTO assignment_decision_log
                (allocation_id, asset_id, employee_id, device_type_id, requested_qty, action,
                 decided_by, request_date, decision_date)
            VALUES
                (NEW.allocation_id, NEW.asset_id, NEW.employee_id, v_device_type_id,
                 NEW.qty_allocated, 'submitted', NEW.requested_by,
                 NEW.requested_at, NEW.requested_at);
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
        SELECT r.request_id, r.device_type_id, r.asset_specification, r.requested_qty, r.created_at
            INTO v_request_id, v_device_type_id, v_asset_spec, v_requested_qty, v_request_date
        FROM asset_requests r WHERE r.resulting_allocation_id = NEW.allocation_id;

        IF v_device_type_id IS NULL THEN
            SELECT device_type_id INTO v_device_type_id FROM assets WHERE asset_id = NEW.asset_id;
        END IF;

        IF NEW.status = 'active' THEN
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by,
                 request_date, decision_date)
            VALUES
                (v_request_id, NEW.allocation_id, NEW.asset_id, NEW.employee_id, v_device_type_id,
                 v_asset_spec, COALESCE(v_requested_qty, NEW.qty_allocated), 'approved',
                 NEW.approved_by, COALESCE(v_request_date, NEW.requested_at), NEW.approved_at);
        ELSIF NEW.status = 'rejected' THEN
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by,
                 request_date, decision_date)
            VALUES
                (v_request_id, NEW.allocation_id, NEW.asset_id, NEW.employee_id, v_device_type_id,
                 v_asset_spec, COALESCE(v_requested_qty, NEW.qty_allocated), 'rejected',
                 NEW.approved_by, COALESCE(v_request_date, NEW.requested_at), now());
        ELSIF NEW.status = 'returned' THEN
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by, notes,
                 request_date, decision_date)
            VALUES
                (v_request_id, NEW.allocation_id, NEW.asset_id, NEW.employee_id, v_device_type_id,
                 v_asset_spec, COALESCE(v_requested_qty, NEW.qty_allocated), 'returned',
                 NEW.received_by, NEW.return_notes,
                 COALESCE(v_request_date, NEW.requested_at), NEW.returned_at);
        ELSIF NEW.status = 'lost' THEN
            -- No dedicated "lost_at" column, and ck_alloc_returned forbids setting returned_at
            -- for any status other than 'returned' - now() is the closest available timestamp,
            -- same pattern as 'rejected' above.
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by, notes,
                 request_date, decision_date)
            VALUES
                (v_request_id, NEW.allocation_id, NEW.asset_id, NEW.employee_id, v_device_type_id,
                 v_asset_spec, COALESCE(v_requested_qty, NEW.qty_allocated), 'lost',
                 NEW.received_by, NEW.return_notes,
                 COALESCE(v_request_date, NEW.requested_at), now());
        ELSIF NEW.status = 'written_off' THEN
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by, notes,
                 request_date, decision_date)
            VALUES
                (v_request_id, NEW.allocation_id, NEW.asset_id, NEW.employee_id, v_device_type_id,
                 v_asset_spec, COALESCE(v_requested_qty, NEW.qty_allocated), 'written_off',
                 NEW.received_by, NEW.return_notes,
                 COALESCE(v_request_date, NEW.requested_at), now());
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: trg_log_asset_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_log_asset_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO assignment_decision_log
            (request_id, employee_id, device_type_id, asset_specification, requested_qty,
             action, request_date, decision_date)
        VALUES
            (NEW.request_id, NEW.employee_id, NEW.device_type_id, NEW.asset_specification,
             NEW.requested_qty, 'submitted', NEW.created_at, NEW.created_at);
    ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status = 'pending_approval' THEN
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by, notes,
                 request_date, decision_date)
            VALUES
                (NEW.request_id, NEW.resulting_allocation_id, NEW.fulfilled_asset_id,
                 NEW.employee_id, NEW.device_type_id, NEW.asset_specification, NEW.requested_qty,
                 'fulfilled', NEW.fulfilled_by, NEW.fulfillment_notes,
                 NEW.created_at, NEW.fulfilled_at);
        ELSIF NEW.status = 'needs_purchase' THEN
            INSERT INTO assignment_decision_log
                (request_id, employee_id, device_type_id, asset_specification, requested_qty,
                 action, decided_by, notes, request_date, decision_date)
            VALUES
                (NEW.request_id, NEW.employee_id, NEW.device_type_id, NEW.asset_specification,
                 NEW.requested_qty, 'needs_purchase', NEW.fulfilled_by, NEW.fulfillment_notes,
                 NEW.created_at, NEW.fulfilled_at);
        ELSIF NEW.status = 'approved' THEN
            INSERT INTO assignment_decision_log
                (request_id, employee_id, device_type_id, asset_specification, requested_qty,
                 action, decided_by, request_date, decision_date)
            VALUES
                (NEW.request_id, NEW.employee_id, NEW.device_type_id, NEW.asset_specification,
                 NEW.requested_qty, 'approved', NEW.approved_by, NEW.created_at, NEW.approved_at);
        ELSIF NEW.status = 'rejected' THEN
            INSERT INTO assignment_decision_log
                (request_id, employee_id, device_type_id, asset_specification, requested_qty,
                 action, decided_by, notes, request_date, decision_date)
            VALUES
                (NEW.request_id, NEW.employee_id, NEW.device_type_id, NEW.asset_specification,
                 NEW.requested_qty, 'rejected', NEW.rejected_by, NEW.rejection_reason,
                 NEW.created_at, NEW.rejected_at);
        ELSIF NEW.status = 'fulfilled' THEN
            INSERT INTO assignment_decision_log
                (request_id, allocation_id, asset_id, employee_id, device_type_id,
                 asset_specification, requested_qty, action, decided_by, notes,
                 request_date, decision_date)
            VALUES
                (NEW.request_id, NEW.resulting_allocation_id, NEW.fulfilled_asset_id,
                 NEW.employee_id, NEW.device_type_id, NEW.asset_specification, NEW.requested_qty,
                 'fulfilled', NEW.fulfilled_by, NEW.fulfillment_notes,
                 NEW.created_at, NEW.fulfilled_at);
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


