CREATE TABLE public.asset_allocations (
    allocation_id integer NOT NULL,
    asset_id text NOT NULL,
    employee_id text NOT NULL,
    qty_allocated integer DEFAULT 1 NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    requested_by text NOT NULL,
    approved_at timestamp with time zone,
    approved_by text,
    allocated_at timestamp with time zone,
    condition_out text,
    expected_return_date date,
    allocation_notes text,
    returned_at timestamp with time zone,
    received_by text,
    condition_in text,
    return_notes text,
    status text DEFAULT 'pending'::text NOT NULL,
    source text DEFAULT 'n8n_form'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    party_type text DEFAULT 'person'::text NOT NULL,
    CONSTRAINT asset_allocations_person_only_chk CHECK ((party_type = 'person'::text)),
    CONSTRAINT asset_allocations_qty_allocated_check CHECK ((qty_allocated > 0)),
    CONSTRAINT asset_allocations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'rejected'::text, 'returned'::text, 'lost'::text, 'written_off'::text]))),
    CONSTRAINT ck_alloc_approved CHECK (((status <> 'active'::text) OR ((approved_at IS NOT NULL) AND (allocated_at IS NOT NULL)))),
    CONSTRAINT ck_alloc_returned CHECK (((status = 'returned'::text) = (returned_at IS NOT NULL)))
);


