--
-- Name: v_daily_it_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_daily_it_summary AS
 SELECT CURRENT_DATE AS report_date,
    ( SELECT count(*) AS count
           FROM public.assignment_decision_log
          WHERE ((assignment_decision_log.decision_date)::date = CURRENT_DATE)) AS activity_events_today,
    ( SELECT count(*) AS count
           FROM public.asset_requests
          WHERE ((asset_requests.created_at)::date = CURRENT_DATE)) AS new_requests_today,
    ( SELECT count(*) AS count
           FROM public.asset_allocations
          WHERE (asset_allocations.status = 'pending'::text)) AS pending_approvals,
    ( SELECT count(*) AS count
           FROM public.asset_requests
          WHERE (asset_requests.status = 'needs_purchase'::text)) AS needs_purchase_backlog;


--
-- Name: v_offboarding_risk; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_offboarding_risk AS
 SELECT a.asset_id,
    a.current_employee_id AS employee_id,
    e.name AS employee_name,
    a.party_type,
    dt.name AS device_type,
    o.name AS office_name,
    a.qty,
    e.date_of_exit,
    a.asset_status
   FROM (((public.assets a
     JOIN public.employees e ON ((e.employee_id = a.current_employee_id)))
     LEFT JOIN public.device_types dt ON ((dt.device_type_id = a.device_type_id)))
     LEFT JOIN public.offices o ON ((o.office_id = a.office_id)))
  WHERE ((a.asset_status = 'in_use'::text) AND (a.party_type = 'person'::text) AND (e.employment_status = 'resigned'::text));


--
-- Name: v_persons; Type: VIEW; Schema: public; Owner: -
