    phone,
    department,
    designation,
    office_id,
    employment_status,
    date_of_joining,
    date_of_exit,
    created_at,
    updated_at,
    party_type
   FROM public.employees
  WHERE (party_type = 'person'::text);


--
-- Name: vendors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendors (
    vendor_id integer NOT NULL,
    name text NOT NULL,
    category text,
    contact_person text,
    email text,
    phone text,
    gstin text,
    address text,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: v_rental_risk; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_rental_risk AS
 SELECT a.asset_id,
    a.vendor_id,
    v.name AS vendor_name,
    a.current_employee_id,
    e.name AS employee_name,
    e.employment_status,
    a.asset_status,
    a.qty,
    a.office_id,
    a.remarks,
    a.acquisition_type,
    s.final_status,
    a.party_type
   FROM (((public.assets a
     JOIN public.employees e ON ((e.employee_id = a.current_employee_id)))
     JOIN public.stg_assets_sheet s ON ((s.asset_id = a.asset_id)))
     LEFT JOIN public.vendors v ON ((v.vendor_id = a.vendor_id)))
  WHERE ((a.party_type = 'person'::text) AND (e.employment_status = 'resigned'::text) AND (lower(TRIM(BOTH FROM s.final_status)) = ANY (ARRAY['with employee'::text, 'at ab office'::text, 'not found'::text, 'not recoverable'::text])));


--
-- Name: v_team_custodians; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_team_custodians AS
 SELECT employee_id,
    name,
    email,
    phone,
    department,
    designation,
    office_id,
    employment_status,
    date_of_joining,
    date_of_exit,
    created_at,
    updated_at,
    party_type
   FROM public.employees
  WHERE (party_type <> 'person'::text);


--
-- Name: v_weekly_it_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_weekly_it_summary AS
 SELECT o.name AS office_name,
    dt.name AS device_type,
    sum(a.qty) AS asset_count,
    COALESCE(sum(a.qty) FILTER (WHERE (a.party_type = 'person'::text)), (0)::bigint) AS held_by_person,
    COALESCE(sum(a.qty) FILTER (WHERE (a.party_type <> 'person'::text)), (0)::bigint) AS held_by_team,
    ( SELECT count(*) AS count
           FROM public.rental_risk_flags rf
          WHERE ((rf.status = 'open'::text) AND (rf.asset_id IN ( SELECT assets.asset_id
                   FROM public.assets
                  WHERE (assets.office_id = o.office_id))))) AS open_rental_risk_flags,
    prev.asset_count AS asset_count_prior_week,
    (sum(a.qty) - COALESCE((prev.asset_count)::bigint, sum(a.qty))) AS delta_vs_prior_week
   FROM (((public.assets a
     JOIN public.offices o ON ((o.office_id = a.office_id)))
     JOIN public.device_types dt ON ((dt.device_type_id = a.device_type_id)))
     LEFT JOIN public.report_weekly_snapshot prev ON (((prev.office_id = a.office_id) AND (prev.device_type_id = a.device_type_id) AND (prev.snapshot_date = ( SELECT max(report_weekly_snapshot.snapshot_date) AS max
           FROM public.report_weekly_snapshot
          WHERE (report_weekly_snapshot.snapshot_date < (date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone))::date))))))
  GROUP BY o.name, o.office_id, dt.name, dt.device_type_id, prev.asset_count;


